-- ============================================================
-- Verificación
-- ============================================================
SELECT c.client_id, c.erp_type, COUNT(f.id) AS flows
FROM clients c
LEFT JOIN flows f ON f.client_id = c.id
WHERE c.client_id IN ('pruebaws','pruebackt','pruebasap','pruebaexcel')
GROUP BY c.client_id, c.erp_type
ORDER BY c.client_id;
